UPDATE lf_ops.reglas AS r SET titulo='Solicitud de recuperación por soporte, sin OTP automático', descripcion='B2B-AUTH-002 acepta correo validado y muestra idéntica respuesta haya cuenta o no. Para una cuenta elegible, LF_AUTH_BOUNDARY abre expediente con soporte, DNI escaneado, aprobadores configurables 1 o 2 según approvers_required de política 20 (inicial 1), aviso al contacto anterior, auditoría y espera de 48 horas. El servidor emite clave temporal de un solo uso solo al cumplirse todos los controles; no crea desafío OTP PASSWORD_RECOVERY, sesión ni permisos.', valor_config='{"gateway":"LF_AUTH_BOUNDARY","route_id":9,"screen_id":52,"ip_hard_limit":"DENY","email_field_id":299,"ip_signal_mode":"PREVENTIVE_ALERT_ONLY","backend_runtime":"SPRING_BOOT_CORE","frontend_runtime":"NEXTJS_STATIC_EXPORT","provider_binding":"OIDC_PROVIDER_PENDING_M1_SPIKE","identity_protocol":"OIDC_JWT","primary_cta_label":"Solicitar recuperación","aws_identity_target":"AMAZON_COGNITO","production_authorized":false,"success_context_scope":"SUPPORT_CASE_PENDING","arbitrary_redirect_url":"DENY","local_identity_decision":"PENDING_ADR_003_M1_SPIKE","anti_enumeration_rule_id":446,"operational_access_grant":"DENY","password_update_route_id":12,"recovery_verify_route_id":11,"authentication_completion":"DENY","password_update_screen_id":53,"recovery_rate_limit_scope":"FUNCTIONAL_OPERATION_ISOLATED","recovery_verify_screen_id":56,"recovery_rate_limit_rule_id":501,"browser_direct_provider_auth":"DENY","operational_session_creation":"DENY","recovery_rate_limit_policy_id":7,"fail_closed_security_policy_id":18,"architecture_alignment_decision":"DEC-B2B-AUTH-PLATFORM-ALIGNMENT-001","server_generates_correlation_id":true,"password_values_in_recovery_email":"DENY","provider_architecture_security_policy_id":23,"password_fields_before_identity_verification":"DENY","recovery_mode":"SUPPORT_DNI_SCANNED","approvers_policy_id":20,"recovery_hold_hours":48,"auto_recovery_otp":"DENY"}'::jsonb WHERE r.id=447 AND r.