UPDATE lf_ops.reglas AS r SET titulo='Validación por soporte de recuperación B2B', descripcion='B2B-AUTH-006 presenta estado genérico de un expediente de soporte, sin envío ni verificación OTP PASSWORD_RECOVERY. El servidor exige DNI escaneado, aprobadores configurables según política 20, aviso previo, auditoría y 48 horas transcurridas antes de emitir clave temporal de uso único. Sin evidencia, bloquear PASSWORD_UPDATE_ONLY y no revelar existencia de cuenta.', valor_config='{"success_scope":"PASSWORD_UPDATE_ONLY","otp_value_logs":"DENY","mfa_satisfaction":"DENY","verify_screen_id":56,"primary_cta_label":"Verificar código","request_screen_id":52,"delivery_execution":"LF_SERVER_ONLY","otp_value_analytics":"DENY","production_authorized":false,"server_side_generation":"REQUIRED","anti_enumeration_rule_id":446,"delivery_provider_status":"PENDING_CREDENTIALS_IMPLEMENTATION","server_side_verification":"REQUIRED","delivery_contract_rule_id":505,"delivery_confirmed_outcome":"DELIVERED","delivery_confirmation_event":"delivered","provider_acceptance_outcome":"ACCEPTED_PENDING_DELIVERY","operational_session_creation":"DENY","delivery_state_contract_rule_id":505,"provider_acceptance_is_delivery":"DENY","webhook_required_before_verify_ui":false,"provider_acceptance_allows_verify_ui":true,"delivery_failure_account_existence_exposure":"DENY","recovery_method":"SUPPORT_DNI_SCANNED","approval_policy_id":20,"hold_hours":48,"auto_otp_challenge":"DENY","temporary_password":"ONE_TIME_AFTER_APPROVAL"}'::jsonb WHERE r.id=493 AND r.codigo='B2B-RULE-AUTH-037' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='b845bb8fe2f4cb700450caea55534b6561287eba9e7ad0c54978a79f6e72ee9a';
