UPDATE lf_ops.reglas AS r SET titulo='Espera de recuperación y estados calculados por servidor', descripcion='B2B-AUTH-006 muestra exclusivamente estados normalizados de expediente y espera de 48 horas calculados server-side; no muestra reenvío OTP ni permite que un temporizador del navegador autorice el desbloqueo. Antes de la aprobación, notificación y vencimiento de espera, no habilita PASSWORD_UPDATE_ONLY. En todos los estados mantiene anti-enumeración.', valor_config='{"hardcoded_expiry":"DENY","verify_screen_id":56,"anti_enumeration_required":true,"hardcoded_resend_countdown":"DENY","numeric_thresholds_in_rule":"DENY","recovery_hold_hours":48,"display_source":"SERVER_RECOVERY_CASE","resend_otp_visible":false}'::jsonb WHERE r.id=494 AND r.codigo='B2B-RULE-AUTH-038' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='481ebfde98e2fc5ca2a709cb739579d79f85a5a582e98d26153386c98b2df0ca';
-- UPDATE B2B-RULE-AUTH-042 before SHA 20ba67e22439a6526b80d9c4fab232f671b1c951b48b9dd465a9cc81f0159521
UPDATE lf_ops.reglas AS r SET titulo='Rate limit aislado de recuperación por soporte', descripcion='Las solicitudes de soporte de B2B-AUTH-002/006 consumen un contador independiente de MFA y correos transaccionales; mismo tratamiento para cuenta existente e inexistente y sujeto derivado del correo canónico mediante secreto server-side. La IP solo eleva señal preventiva de abuso; nunca bloquea por sí sola. Ventanas y umbrales provienen de la política central, sin duplicarlos.', valor_config='{"ip_escalation":"RISK_OR_ANTIBOT","ip_hard_limit":"DENY","resource_code":"AUTH_SUPPORT_RECOVERY_REQUEST","ip_signal_mode":"PREVENTIVE_ALERT_ONLY","counter_subject":"PRIVACY_PRESERVING_DERIVED_SUBJECT_KEY","rate_limit_policy_id":7,"abuse_security_policy_id":22,"anti_enumeration_required":true,"counter_subject_derivation":"HMAC(SERVER_CANONICAL_EMAIL_VALUE,SERVER_SECRET)","numeric_thresholds_in_rule":"DENY","anti_bot_security_policy_id":17,"account_existence_dependency":"DENY","functional_operation_isolation":"REQUIRED","counter_subject_secret_location":"RUNTIME_SECRET_OUTSIDE_LF_OPS","counter_consumed_when_account_unknown":true,"other_otp_operation_counter_interference":"DENY","transactional_email_counter_interference":"DENY","functional_operation":"SUPPORT_RECOVERY","automatic_otp_send":"DENY"}'::jsonb WHERE r.id=501 AND r.codigo='B2B-RULE-AUTH-042' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='20ba67e22439a6526b80d9c4fab232f671b1c951b48b9dd465a9cc81f0159521';
-- UPDATE REG_CLIENT_RECOVERY_IDV_OUTCOME_001 before SHA 772b74d119e1b471e997432273585bc410f081567bd87c26c58dcfacfb4eb30d
UPDATE lf_ops.reglas AS r SET titulo='Resultado IDV y comprobante manual Q11 distintos', descripcion='Un resultado automático IDV VERIFIED solo procede del proveedor integrado y verificado, nunca de una simulación ni del DNI solo. En forma separada, soporte Q11 emite comprobante server-side tras escaneo DNI, creador distinto del aprobador, avisos a celular y correo anteriores, auditoría y 48 horas de espera. Ni falla, ni falta de proveedor, ni caso en revisión autoriza reasignación o acceso. La UI no ve respuestas crudas de proveedor ni documentos.', valor_config='{"flow":"RECOVERY_FLOW","front":"CLIENTE","outcomes":{"IDENTITY_VALIDATION_DENIED":{"next":"GENERIC_RECOVERY_FAILURE","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_VERIFIED":{"rebind":"ALLOW_VIA_REG_CLIENT_RECOVERY_REBIND_ATOMIC_001","operational_access":"AFTER_SUCCESSFUL_REBIND_ONLY"},"IDENTITY_VALIDATION_RISK_BLOCKED":{"next":"TEMPORARY_SECURITY_STOP","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_RETRYABLE_FAILURE":{"next":"RETRY_SUBJECT_TO_PROVIDER_POLICY","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_SERVICE_UNAVAILABLE":{"next":"RETRY_LATER_NO_BYPASS","rebind":"DENY","operational_access":"DENY"}},"allowed_outcomes":["IDENTITY_VALIDATION_VERIFIED","IDENTITY_VALIDATION_RETRYABLE_FAILURE","IDENTITY_VALIDATION_DENIED","IDENTITY_VALIDATION_RISK_BLOCKED","IDENTITY_VALIDATION_SERVICE_UNAVAILABLE"],"source_rule_code":"REG_CLIENT_RECOVERY_IDV_STEPUP_001","source_decision_numbers":[71,103,104],"support_can_override_outcome":"DENY","provider_result_normalization":"SERVER_SIDE_REQUIRED","provider_raw_payload_to_client":"DENY","provider_specific_reason_to_client":"DENY","q11_manual_proof":"Q11_TWO_DISTINCT_APPROVERS_48H","manual_approval_not_provider_verified":true,"selfie":"UNDECIDED"}'::jsonb WHERE r.id=511 AND r.codigo='REG_CLIENT_RECOVERY_IDV_OUTCOME_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='772b74d119e1b471e997432273585bc410f081567bd87c26c58dcfacfb4eb30d';
-- UPDATE REG_CLIENT_RECOVERY_IDV_STEPUP_001 before SHA 95185d992bf1c7e03773796030024b3642f26757fcea899f1ed02fda681d42b4
UPDATE lf_ops.reglas AS r SET titulo='Step-up Cliente con soporte Q11 e IDV sin seleccionar', descripcion='REC_001 permite, sin celular anterior, la ruta Q11 con DNI escaneado, dos personas distintas (una registra y otra aprueba), notificación a celular y correo anteriores, auditoría y 48 horas de espera. El celular actual debe seguir verificado en ONB_002, sin que su OTP sustituya identidad. El proveedor IDV no está elegido y selfie no está decidida: ninguno se presume implementado. Riesgo HIGH conserva bloqueo y revisión.', valor_config='{"flow":"RECOVERY_FLOW","front":"CLIENTE","triggers":["OLD_PHONE_UNAVAILABLE","PHONE_MULTI_DNI_RISK_HIGH"],"raw_pii_in_logs":"DENY","provider_binding":"PENDING_CANONICAL_IDV_PROVIDER","rebind_rule_code":"REG_CLIENT_RECOVERY_REBIND_ATOMIC_001","support_override":"DENY","target_route_code":"CLIENT_RECOVERY","raw_pii_in_analytics":"DENY","target_screen_mapping":"REC_001","source_decision_numbers":[71,103,104],"required_identity_outcome":"IDV_VERIFIED_OR_Q11_MANUAL_PROOF","provider_agnostic_contract":true,"current_phone_control_source":"ONB_002_SAME_SERVER_SESSION","source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","account_rebind_before_verified":"DENY","current_phone_control_required":true,"dni_knowledge_alone_sufficient":false,"raw_provider_payload_to_client":"DENY","knowledge_based_questions_default":"DENY","operational_access_before_verified":"DENY","current_phone_control_alone_sufficient":false,"email_otp_approved_as_client_recovery_factor":false,"support_q11_path":"TWO_PERSON_DNI_48H","support_approvers_required":2,"previous_contact_notice":["PHONE","EMAIL"],"hold_hours":48,"selfie":"UNDECIDED"}'::jsonb WHERE r.id=510 AND r.codigo='REG_CLIENT_RECOVERY_IDV_STEPUP_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='95185d992bf1c7e03773796030024b3642f26757fcea899f1ed02fda681d42b4';
-- UPDATE REG_CLIENT_RECOVERY_PHONE_CONTROL_001 before SHA 2043f8575951db0e61cdeeec58624f22c035425e929096ae973b9ef159a89dfa
UPDATE lf_ops.reglas AS r SET titulo='Celular actual verificado y recuperación Q11 sin el anterior', descripcion='REC_001 reutiliza el celular actual verificado en ONB_002 mientras la misma sesión siga válida. Si el anterior está disponible, verificar su OTP por la ruta existente; si no, pasar a soporte Q11 con DNI escaneado, dos personas distintas, avisos a celular/correo anteriores, auditoría y 48 horas. Ningún camino permite reasociación antes del comprobante válido ni revela existencia de cuenta.', valor_config='{"source_state":"RECOVERY_FLOW","source_screen":"ONB_003","target_route_code":"CLIENT_RECOVERY","current_phone_role":"NEW_VERIFIED_PHONE_CANDIDATE","reask_current_phone":"DENY","show_full_old_phone":"DENY","ask_old_phone_access":true,"old_phone_accessible":"VERIFY_OLD_PHONE_OTP","old_phone_otp_channel":"whatsapp","old_phone_unavailable":"SUPPORT_Q11_DNI_TWO_PERSON_48H","target_screen_mapping":"REC_001","source_decision_number":103,"old_phone_otp_operation":"OTP_OP_RECUPERAR_CLAVE","old_phone_otp_field_code":"CAMPO_OTP_CODE","repeat_current_phone_otp":false,"source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","current_verified_phone_source":"ONB_001_PLUS_ONB_002","identity_validation_rule_code":"REG_IDV_PROGRESSIVE_001","same_session_binding_required":true,"previous_contact_notice":["PHONE","EMAIL"],"manual_q11_distinct_people":true}'::jsonb WHERE r.id=507 AND r.codigo='REG_CLIENT_RECOVERY_PHONE_CONTROL_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='2043f8575951db0e61cdeeec58624f22c035425e929096ae973b9ef159a89dfa';
-- UPDATE REG_CLIENT_RECOVERY_REBIND_ATOMIC_001 before SHA 88b650cd7f9c964281f40b23823c3000b0da9bf91d3b5ef423d453f2129f5557
UPDATE lf_ops.reglas AS r SET titulo='Reasignación Cliente atómica e idempotente tras comprobante Q11', descripcion='Solo reasociar celular a cuenta Cliente con sesión ONB_002 válida, verificación de unicidad y una prueba aprobada. Sin celular anterior, admitir comprobante Q11 server-side tras DNI escaneado, creación y aprobación por personas distintas, aviso a celular/correo anteriores, auditoría y espera 48 horas. Selfie no autorizada; IDV externo no elegido. Antes de commit revalidar riesgo HIGH y revocar acceso y sesiones del principal anterior; evitar escrituras parciales o dobles vínculos.', valor_config='{"idempotency":"REQUIRED","atomic_commit":"REQUIRED","audit_storage":"lf_client.security_events","auth_provider":"SUPABASE_AUTH","audit_rule_code":"REG_AUD_004","raw_dni_in_logs":"DENY","raw_phone_in_logs":"DENY","concurrent_conflict":"GENERIC_FAILURE_NO_PARTIAL_COMMIT","auth_principal_rebind":"UPDATE_CLIENT_ACCOUNT_AUTH_USER_ID_ATOMICALLY_AFTER_VERIFIED_RECOVERY","source_decision_number":103,"account_binding_storage":"lf_client.client_accounts + lf_client.client_phone_bindings","old_phone_otp_operation":"OTP_OP_RECUPERAR_CLAVE","accepted_recovery_proofs":["OLD_PHONE_OTP_VERIFIED","IDENTITY_VALIDATION_VERIFIED","SUPPORT_Q11_TWO_PERSON_DNI_48H_APPROVED"],"current_phone_otp_source":"ONB_002_SAME_SERVER_SESSION","precommit_risk_rule_code":"REG_RISK_PHONE_MULTI_DNI_001","identity_stepup_rule_code":"REG_CLIENT_RECOVERY_IDV_STEPUP_001","current_phone_otp_required":true,"identity_outcome_rule_code":"REG_CLIENT_RECOVERY_IDV_OUTCOME_001","post_rebind_access_rule_code":"REG_CLIENT_RECOVERY_ACCESS_AFTER_REBIND_001","source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","target_phone_uniqueness_rule":"REG_UNI_002","old_principal_business_access":"REVOKE_IMMEDIATELY","old_principal_session_revocation":"SERVER_SIDE_REQUIRED","operational_access_before_commit":"DENY","invalidate_previous_phone_binding":true,"manual_q11_hold_hours":48,"manual_q11_distinct_approver":true,"manual_q11_previous_notifications":["PHONE","EMAIL"],"selfie":"UNDECIDED"}'::jsonb WHERE r.id=508 AND r.codigo='REG_CLIENT_RECOVERY_REBIND_ATOMIC_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='88b650cd7f9c964281f40b23823c3000b0da9bf91d3b5ef423d453f2129f5557';
-- UPDATE REG_ONB002_UI_STATES_001 before SHA 60d5b3105f550a927efe8bcaede671cbd9e8afef83b610ec68bc18207382f8b0
UPDATE lf_ops.reglas AS r SET titulo='ONB_002 — estados OTP y SMS por soporte', descripcion='ONB_002 conserva estados A normal, B contador agotado y C OTP incorrecto; tiempos y CTA consumen contratos server-side y tokens de diseño. Ante fallo de WhatsApp no activa SMS automáticamente. SMS Intico solo aparece por contingencia habilitada por soporte con auditoría; en caso contrario permanece oculto. El OTP demuestra control del celular, no identidad civil.', valor_config='{"title":"Te enviamos un código","state_A":{"code":"NORMAL","timer_text":"(00:45)","resend_label":"Reenviar código","resend_muted":true,"cta_visual_state":"ACTIVE_GREEN","timer_underlined":false,"resend_underlined":true},"state_B":{"code":"COUNTER_EXHAUSTED","resend_label":"Reenviar código","cta_visual_state":"PRIMARY_TOKEN","sms_fallback_visibility":"HIDE_UNLESS_SUPPORT_ACTIVATED","runtime_timing_status":"SERVER_POLICY_REQUIRED"},"state_C":{"code":"INVALID_CODE","error_copy":"Código incorrecto. Revisa e intenta de nuevo.","otp_border":"ERROR_RED","cta_visual_state":"ACTIVE_GREEN"},"otp_slots":6,"layout_shift":false,"runtime_refs":["REG_RATE_005","REG_SEG_001","REG_SEG_002","OTP_POL_DEFAULT"],"vertical_anchors":{"h1":"MATCH_ONB001_H1","trust_row":"MATCH_ONB001_TRUST_ROW","primary_cta":"MATCH_ONB001_PRIMARY_CTA"},"error_line_reserved":true,"source_visual_decision":"VD_CLIENT_ONB002_WEB_V06_20260820","sms_fallback_mode":"SUPPORT_ONLY","sms_provider":"INTICO","auto_sms_fallback":"DENY"}'::jsonb WHERE r.id=568 AND r.codigo='REG_ONB002_UI_STATES_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='60d5b3105f550a927efe8bcaede671cbd9e8afef83b610ec68bc18207382f8b0';
-- INSERT candidate B2B-RULE-RECOVERY-SUPPORT-001; link only screens B2B-AUTH-002, B2B-AUTH-003, B2B-AUTH-006
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('B2B-RULE-RECOVERY-SUPPORT-001','AUTH','Recuperación asistida B2B con 48 horas y clave temporal','Soporte registra DNI escaneado; la política central 20 determina 1 o 2 aprobadores (inicial 1). Exigir aviso al contacto previo, auditoría y 48 horas antes de emitir clave temporal de uso único limitada a contraseña nueva. No ofrecer OTP PASSWORD_RECOVERY ni establecer sesión antes de nuevo login y MFA conforme a política. Si falta evidencia, bloquear sin revelar existencia de usuario.','{"approvers_policy_id":20,"initial_approvers_required":1,"hold_hours":48,"document":"SCANNED_DNI","previous_contact_notification":true,"audit":true,"temporary_password":"ONE_TIME","state":"PROPOSED_NOT_ACTIVE"}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,pantalla_id,'CANDIDATO. HUMAN_GATES_OPEN. NO_PRODUCTION.' FROM inserted CROSS JOIN (VALUES (52),(53),(56)) AS destination(pantalla_id);
-- INSERT candidate REG_CLIENT_RECOVERY_SUPPORT_Q11_001; link only screens REC_001
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('REG_CLIENT_RECOVERY_SUPPORT_Q11_001','RECOVERY','Recuperación Cliente Q11 por dos personas','Sin celular anterior, soporte registra DNI escaneado y una segunda persona distinta aprueba. Avisar al celular y correo anteriores; conservar auditoría y bloquear 48 horas antes de emitir comprobante apto para rebind atómico del celular verificado en ONB_002. Selfie y proveedor IDV quedan sin decidir; no fingir evidencia ni liberar cuenta antes de completar el proceso.','{"approvers_required":2,"hold_hours":48,"scanned_dni":true,"notifications":["PREVIOUS_PHONE","PREVIOUS_EMAIL"],"creator_differs_from_approver":true,"selfie":"UNDECIDED","idv":"PENDING_SELECTION","state":"PROPOSED_NOT_ACTIVE"}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,pantalla_id,'CANDIDATO. HUMAN_GATES_OPEN. NO_PRODUCTION.' FROM inserted CROSS JOIN (VALUES (58)) AS destination(pantalla_id);
-- INSERT candidate REG_ONB002_SMS_SUPPORT_GATE_001; link only screens ONB_002
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('REG_ONB002_SMS_SUPPORT_GATE_001','AUTH','SMS Intico como contingencia no automática','En ONB_002 el canal de OTP Cliente es WhatsApp. Ante falla no activar fallback SMS automáticamente: registrar incidente, permitir reintento según política y comunicar a soporte. Solo soporte puede habilitar SMS Intico con evidencia auditable; el frontend no selecciona proveedor, no duplica OTP ni convierte control de teléfono en identidad personal.','{"channel":"WHATSAPP","contingency":"INTICO_SMS","activation":"SUPPORT_ONLY","auto_fallback":"DENY","state":"PROPOSED_NOT_ACTIVE"}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,pantalla_id,'CANDIDATO. HUMAN_GATES_OPEN. NO_PRODUCTION.' FROM inserted CROSS JOIN (VALUES (2)) AS destination(pantalla_id);
